# pytest test suite for the /pet/{petId}/uploadImage endpoint

import pytest
import os

@pytest.mark.parametrize("petId,additionalMetadata,status_code,expected_response", [
    (123, "metadata", 200, {"code": 200, "type": "response", "message": "Success"}),
    (123, None, 200, {"code": 200, "type": "response", "message": "Success"}),
    (99999, None, 404, None),  # Pet not found
    (123, "metadata", 400, None),  # No file provided
])
def test_pet_upload_image(api_helper, valid_api_key, petId, additionalMetadata, status_code, expected_response):
    """
    Test the /pet/{petId}/uploadImage endpoint for different response scenarios.

    Args:
        petId (int): Pet ID path parameter.
        additionalMetadata (str): Optional metadata query parameter.
        status_code (int): Expected status code.
        expected_response (dict): Expected response body.
    """
    headers = {'Authorization': f"Bearer {valid_api_key}"}
    
    payload = None
    if status_code == 200:
        # Sending a valid file in payload
        payload = {'file': ('image.jpg', open(os.path.join(os.path.dirname(__file__), 'sample.jpg'), 'rb'))}
    elif status_code == 400:
        # Simulating a case with no file uploaded
        payload = None

    endpoint = f"pet/{petId}/uploadImage"
    params = {"additionalMetadata": additionalMetadata} if additionalMetadata else None

    response = api_helper.make_request(endpoint=endpoint, params=params, headers=headers, method="POST", data=payload)
    assert response.status_code == status_code

    if expected_response:
        response_data = response.json()
        assert response_data == expected_response


